with valid_inventory as (select * from inventory where store_id in (4, 5)), InventoryStats as (select case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end as last_restock_cohort, product_id, round(avg(quantity), 2) as avg_quantity, count(*) as inventory_count from valid_inventory group by case when year(last_restock) < 2024 then 'before_2024' when year(last_restock) = 2024 then '2024' else 'after_2024' end, product_id) select last_restock_cohort, product_id, avg_quantity, inventory_count from InventoryStats where avg_quantity < 20;
